  // do aposto ("Peruggia, the thief"), nunca complemento dele ("Louis Lépine, a rival of the thief").
  const N = `(?:${alts.join('|')})`
  const ADJ = String.raw`(?:(?!(?:of|the|a|an|for|with|by|from|against|to|in|on|at|and|or|not|never|no)(?![\p{L}]))[\p{Ll}-]+\s+){0,2}?`
